<template>
  <div id="app">
    <router-view :current-lang="currentLang" @change-lang="changeLang" />
  </div>
</template>

<script>
export default {
  name: 'App',
  data() {
    return {
      currentLang: localStorage.getItem('astro_lang') || 'zh'
    }
  },
  methods: {
    changeLang(lang) {
      this.currentLang = lang
      localStorage.setItem('astro_lang', lang)
    }
  }
}
</script>

