<script>
import Navbar from '../components/Navbar.vue'
import Footer from '../components/Footer.vue'
import { languages } from '../assets/languages.js'

export default {
  name: 'Home',
  props: {
    currentLang: {
      type: String,
      default: 'zh'
    }
  },
  components: {
    Navbar,
    Footer
  },
  data() {
    return {
      currentSlide: 0,
      slideStep: 25,
      carouselInterval: null,
      recipientEmails: ['270302301@qq.com', 'colin270302301@gmail.com'],
      contactForm: {
        name: '',
        email: '',
        phone: '',
        message: ''
      },
      partners: [
        { name: 'Shopify', icon: 'shopify' },
        { name: 'WooCommerce', icon: 'wordpress' },
        { name: 'Amazon', icon: 'amazon' },
        { name: 'eBay', icon: 'ebay' },
        { name: 'AliExpress', icon: 'shopping-cart' },
        { name: 'FedEx', icon: 'truck' },
        { name: 'DHL', icon: 'truck-fast' },
        { name: 'UPS', icon: 'truck-loading' }
      ]
    }
  },
  computed: {
    t() {
      return languages[this.currentLang] || languages.zh
    }
  },
  methods: {
    changeLang(lang) {
      this.$emit('change-lang', lang)
    },
    nextSlide() {
      if (this.currentSlide < 3) {
        this.currentSlide++
      }
    },
    prevSlide() {
      if (this.currentSlide > 0) {
        this.currentSlide--
      }
    },
    getCapabilityIcon(index) {
      const icons = ['store', 'handshake-angle', 'check-circle', 'boxes-stacked', 'truck-fast', 'headset']
      return icons[index] || 'star'
    },
    getBusinessModelIcon(index) {
      const icons = ['truck-fast', 'flag', 'box-open', 'warehouse', 'palette']
      return icons[index] || 'star'
    },
    getSupplyChainIcon(index) {
      const icons = ['route', 'arrows-rotate', 'pencil', 'circle-check', 'eye']
      return icons[index] || 'star'
    },
    getOperatingSystemIcon(index) {
      const icons = ['truck-fast', 'palette', 'warehouse', 'truck', 'shield-check', 'headset']
      return icons[index] || 'star'
    },
    handleLogoError(event) {
      event.target.src = 'https://logo.clearbit.com/google.com'
    },
    handleContactSubmit() {
      // Send notification to WeChat via Server酱
      const sendkey = 'SCT342335TIsFNci9EpNmO1RHEbA2amisa'
      const notifyTitle = `Astro Website Inquiry - ${this.contactForm.name || 'Visitor'}`
      const notifyDesp = `**Name:** ${this.contactForm.name}\n**Email:** ${this.contactForm.email}\n**Phone:** ${this.contactForm.phone}\n\n**Message:**\n${this.contactForm.message}`
      
      fetch(`https://sctapi.ftqq.com/${sendkey}.send?title=${encodeURIComponent(notifyTitle)}&desp=${encodeURIComponent(notifyDesp)}`)
        .then(response => response.json())
        .then(data => {
          console.log('Server酱通知发送成功:', data)
          // 显示成功提示
          alert('提交成功！我们会尽快与您联系。')
          // 清空表单
          this.contactForm = {
            name: '',
            email: '',
            phone: '',
            message: ''
          }
        })
        .catch(error => {
          console.error('Server酱通知发送失败:', error)
          // 显示失败提示
          alert('提交失败，请稍后重试。')
        })
    }
  },
  mounted() {
    if (window.innerWidth <= 480) {
      this.slideStep = 100
    } else if (window.innerWidth <= 768) {
      this.slideStep = 50
    }
    // 自动轮播
    this.carouselInterval = setInterval(() => {
      this.nextSlide()
    }, 3000)
  },
  beforeUnmount() {
    // 清除定时器
    if (this.carouselInterval) {
      clearInterval(this.carouselInterval)
    }
  }
}
</script>

